INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_MASONIC','Masonic / Rosicrucian Era (manifestos and speculative lodges to present)',1600,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_YATES_ROSICRUCIAN','secondary scholarship','Frances A. Yates, The Rosicrucian Enlightenment (1972)','Rosicrucian manifestos, Christian Rosenkreutz legend, the Invisible College, and early-modern Hermetic-esoteric reform.'),
 ('SRC_MACKEY_FREEMASONRY','secondary scholarship','Albert G. Mackey, An Encyclopaedia of Freemasonry and Its Kindred Sciences (1874; rev. eds.)','Masonic symbolism, ritual, and legend: G.A.O.T.U., Hiram Abiff, the pillars Jachin and Boaz, and the Royal Arch word Jahbulon.')
INSERT INTO _e VALUES
 ('ENT_MAS_LODGE','The Masonic Lodge (Craft Freemasonry)','tradition_hub','Institution','Masonic/Rosicrucian','fraternity; initiation; moral allegory','B','Hub for organized speculative Freemasonry, a globally practiced fraternal-initiatic system (Grand Lodge of England 1717 onward) whose ritual symbolism is the attestation base for these entities.'),
 ('ENT_MAS_ROSICRUCIAN','The Brotherhood of the Rosy Cross (Rosicrucianism)','tradition_hub','Institution','Masonic/Rosicrucian','Hermetic-Christian esotericism; reform; healing','B','Hub for Rosicrucianism, an esoteric current launched by the early-17th-c. manifestos and continued by practicing modern orders (AMORC, SRIA, Rosicrucian Fellowship).'),
 ('ENT_MAS_GAOTU','The Great Architect of the Universe (G.A.O.T.U.)','Cosmic builder','Deity','Masonic/Rosicrucian','creation; divine craftsmanship; cosmic order','B','Non-sectarian name of God required of Masonic candidates and invoked in lodge ritual; a deity sincerely affirmed (in varied confessional terms) by practicing Freemasons worldwide.'),
 ('ENT_MAS_HIRAM_ABIFF','Hiram Abiff','Legendary figure','Legendary figure','Masonic/Rosicrucian','master-craft; fidelity; death and raising','B','The murdered master-builder of Solomon''s Temple in the Masonic Hiramic legend, ritually personified by the candidate in the Third Degree of practiced Craft Masonry.'),
 ('ENT_MAS_JACHIN','Jachin (the pillar)','Cult object','Sacred object','Masonic/Rosicrucian','establishment; threshold; temple symbolism','B','Personified right-hand pillar of Solomon''s porch in Masonic ritual symbolism (lecture of the Fellow Craft); a working ritual symbol, not the biblical priest. Homonym/parallel to scriptural pillar named in 1 Kings 7.'),
 ('ENT_MAS_BOAZ','Boaz (the pillar)','Cult object','Sacred object','Masonic/Rosicrucian','strength; threshold; temple symbolism','B','Personified left-hand pillar of Solomon''s porch in Masonic ritual symbolism. HOMONYM: distinct from the biblical Boaz (ancestor of David), entity ENT_ISR_BOAZ; this is the Temple pillar of 1 Kings 7 as used in lodge symbolism.'),
 ('ENT_MAS_JAHBULON','Jahbulon','Divine name/principle','Divine name/principle','Masonic/Rosicrucian','ineffable name; Royal Arch mystery','C','Composite sacred word disclosed in older Royal Arch Masonic ritual, traditionally parsed as conjoined divine names; a ritually-used (and controversy-attended) name within practiced Royal Arch Masonry, modeled neutrally.'),
 ('ENT_MAS_CHRISTIAN_ROSENKREUTZ','Christian Rosenkreutz','Legendary figure','Legendary figure','Masonic/Rosicrucian','founder-sage; Hermetic wisdom; hidden adeptship','B','Legendary founder of the Rosicrucian brotherhood narrated in the Fama and Chymical Wedding; revered as an archetypal adept within practicing Rosicrucian orders.'),
 ('ENT_MAS_INVISIBLE_COLLEGE','The Invisible College','Initiate order','Collective','Masonic/Rosicrucian','hidden fellowship of adepts; reform; healing','B','The unseen confraternity of Rosicrucian adepts proclaimed in the manifestos; a believed-in body of hidden masters within Rosicrucian practice and a template for later occult orders. Distinct from the Rosicrucian tradition-hub (ENT_MAS_ROSICRUCIAN) — this is the body of adepts itself.');
