INSERT INTO _p VALUES
 ('ENT_MAS_LODGE','PER_MASONIC','Hub for organized speculative Freemasonry, a globally practiced fraternal-initiatic system (Grand Lodge of England 1717 onward) whose ritual symbolism is the attestation base for these entities.'),
 ('ENT_MAS_ROSICRUCIAN','PER_MASONIC','Hub for Rosicrucianism, an esoteric current launched by the early-17th-c. manifestos and continued by practicing modern orders (AMORC, SRIA, Rosicrucian Fellowship).'),
 ('ENT_MAS_GAOTU','PER_MASONIC','Non-sectarian name of God required of Masonic candidates and invoked in lodge ritual; a deity sincerely affirmed (in varied confessional terms) by practicing Freemasons worldwide.'),
 ('ENT_MAS_HIRAM_ABIFF','PER_MASONIC','The murdered master-builder of Solomon''s Temple in the Masonic Hiramic legend, ritually personified by the candidate in the Third Degree of practiced Craft Masonry.'),
 ('ENT_MAS_JACHIN','PER_MASONIC','Personified right-hand pillar of Solomon''s porch in Masonic ritual symbolism (lecture of the Fellow Craft); a working ritual symbol, not the biblical priest. Homonym/parallel to scriptural pillar named in 1 Kings 7.'),
 ('ENT_MAS_BOAZ','PER_MASONIC','Personified left-hand pillar of Solomon''s porch in Masonic ritual symbolism. HOMONYM: distinct from the biblical Boaz (ancestor of David), entity ENT_ISR_BOAZ; this is the Temple pillar of 1 Kings 7 as used in lodge symbolism.'),
 ('ENT_MAS_JAHBULON','PER_MASONIC','Composite sacred word disclosed in older Royal Arch Masonic ritual, traditionally parsed as conjoined divine names; a ritually-used (and controversy-attended) name within practiced Royal Arch Masonry, modeled neutrally.'),
 ('ENT_MAS_CHRISTIAN_ROSENKREUTZ','PER_MASONIC','Legendary founder of the Rosicrucian brotherhood narrated in the Fama and Chymical Wedding; revered as an archetypal adept within practicing Rosicrucian orders.'),
 ('ENT_MAS_INVISIBLE_COLLEGE','PER_MASONIC','The unseen confraternity of Rosicrucian adepts proclaimed in the manifestos; a believed-in body of hidden masters within Rosicrucian practice and a template for later occult orders. Distinct from the Rosicrucian tradition-hub (ENT_MAS_ROSICRUCIAN) — this is the body of adepts itself.');
INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_MAS_GAOTU','member_of','ENT_MAS_LODGE','high','G.A.O.T.U. is the deity invoked in Craft Masonic ritual; anchors to the lodge hub.'),
 ('ENT_MAS_HIRAM_ABIFF','member_of','ENT_MAS_LODGE','high','Hiram Abiff is the central legendary figure of Craft Masonry''s Third Degree.'),
 ('ENT_MAS_JACHIN','member_of','ENT_MAS_LODGE','high','The pillar Jachin is a core symbolic object of the Masonic lodge.'),
 ('ENT_MAS_BOAZ','member_of','ENT_MAS_LODGE','high','The pillar Boaz is a core symbolic object of the Masonic lodge.'),
 ('ENT_MAS_JAHBULON','member_of','ENT_MAS_LODGE','medium','Jahbulon belongs to Royal Arch Masonry, a continuation of the Craft lodge system.'),
 ('ENT_MAS_CHRISTIAN_ROSENKREUTZ','member_of','ENT_MAS_ROSICRUCIAN','high','Christian Rosenkreutz is the legendary founder of the Rosicrucian brotherhood hub.'),
 ('ENT_MAS_INVISIBLE_COLLEGE','member_of','ENT_MAS_ROSICRUCIAN','high','The Invisible College is the brotherhood organ of the Rosicrucian current.'),
 ('ENT_MAS_INVISIBLE_COLLEGE','associated_with','ENT_MAS_CHRISTIAN_ROSENKREUTZ','high','The manifestos present the Brotherhood of the Rosy Cross as founded by and centered on Christian Rosenkreutz.'),
 ('ENT_MAS_JACHIN','paired_with','ENT_MAS_BOAZ','high','Jachin and Boaz are the inseparable twin pillars of Solomon''s porch in Masonic symbolism.'),
 ('ENT_MAS_HIRAM_ABIFF','associated_with','ENT_ISR_SOLOMON','high','The Hiramic legend casts Hiram Abiff as master-builder of King Solomon''s Temple.'),
 ('ENT_MAS_JACHIN','associated_with','ENT_ISR_SOLOMON','medium','The pillars Jachin and Boaz stood at the porch of Solomon''s Temple in the legend the lodge draws on.'),
 ('ENT_MAS_GAOTU','reception_of','ENT_HER_DEMIURGE','medium','The Masonic image of God as cosmic Architect/Craftsman receives the Hermetic-Platonic demiurgic-craftsman conception of the divine maker.'),
 ('ENT_MAS_ROSICRUCIAN','reception_of','ENT_HER_TRISMEGISTUS','high','Rosicrucianism is heavily Hermetic, taking up the prisca theologia of Hermes Trismegistus as a wisdom source.'),
 ('ENT_MAS_INVISIBLE_COLLEGE','aligned_with','ENT_MOD_SECRET_CHIEFS','medium','The Rosicrucian hidden brotherhood of adepts is the prototype later occult orders developed into the doctrine of unseen Secret Chiefs.');
